INSERT INTO reviews (sku, rating, title, body, author_name, is_verified, is_approved, created_at) VALUES
  ('AUD-01M325429', 5, 'Correct fit, sealed properly', 'Second one of these I have bought, this time for the RS4 B7. Dimensions matched the outgoing filter to the millimetre. It dropped straight into the housing and the cap torqued to spec first go. Result is no leaks at all after several hundred miles.', 'Thomas Nair', true, TRUE, '2026-04-20T06:37:57.179Z'),
  ('AUD-01M325429', 5, 'Good pleat count', 'Bought for a 2009 Q5 8R. Dimensions matched the outgoing filter to the millimetre. The old one practically fell apart coming out; this went in cleanly. Result is throttle response feels crisper than it did on the clogged original. Will be back for the other side.', 'Rajesh Almeida', true, TRUE, '2026-05-04T05:56:53.030Z'),
  ('AUD-01M325429', 5, 'Genuine quality for less', 'Went on my A7 4G 2.0 TFSI at 168k miles. The rubber seal is supple and sat in its groove without coaxing. I pre-oiled the seal before fitting and there has not been a drop since. Result is oil pressure comes up as quickly on a cold start as it always has. No complaints at all.', 'Chidi Moreau', true, TRUE, '2025-07-25T15:33:03.504Z'),
  ('AUD-01M325429', 5, 'No leaks, no fuss', 'Second one of these I have bought, this time for the TT 8J. I changed it with the oil at the same service interval. Dimensions matched the outgoing filter to the millimetre. Result is the musty smell from the vents has completely gone.', 'Elena Rossi', true, TRUE, '2026-02-22T21:07:02.545Z'),
  ('AUD-01M325429', 5, 'Right filter every time', 'Cross-referenced the OE number against my 2013 Q7 4L before ordering. The pleat count is visibly higher than the supermarket filter I had been using. Two minutes behind the glovebox once I had the tabs released. Result is oil pressure comes up as quickly on a cold start as it always has.', 'Nadia Hoffmann', false, TRUE, '2026-03-20T12:55:24.922Z'),
  ('AUD-01M325429', 5, 'Exactly what the service needed', 'Ordered this for my Q5 8R after the original gave up at 119k. I pre-oiled the seal before fitting and there has not been a drop since. The rubber seal is supple and sat in its groove without coaxing. Result is shifts are smoother now the transmission has clean fluid and a fresh filter.', 'Laura Zimmer', true, TRUE, '2025-03-29T08:37:10.172Z'),
  ('AUD-01M325429', 5, 'Exactly what the service needed (Q5 8R)', 'Replacement for my 2011 Q5 8R 2.0 TFSI. The media feels dense and the end caps are properly bonded rather than glued on thin. I changed it with the oil at the same service interval. Result is the musty smell from the vents has completely gone.', 'Niall Ellery', true, TRUE, '2026-06-16T23:38:12.178Z'),
  ('AUD-022905715D', 5, 'Straight fix for a rough idle', 'Second one of these I have bought, this time for the A6 C8. The part number on the body matches the OE reference exactly. A smear of dielectric grease went on the boot before it was seated. Result is it pulls cleanly through the rev range again with no stumble under load.', 'Talia Larsen', true, TRUE, '2025-05-28T08:43:04.672Z'),
  ('AUD-022905715D', 5, 'Cured my P0303', 'Ordered this for my Q5 FY after the original gave up at 98k. The spring contact is firm and seated with a definite click. I replaced all four at once rather than chase them one at a time. Result is fuel economy went back to normal within a tank. No complaints at all.', 'Viktor Weiss', false, TRUE, '2026-08-13T16:40:03.060Z'),
  ('AUD-022905715D', 5, 'Misfire cleared instantly', 'Cross-referenced the OE number against my 2016 Q7 4M before ordering. The spring contact is firm and seated with a definite click. I swapped it on the roadside when the car dropped a cylinder on the way home. Result is cold starts are smooth instead of shaking the whole car. Exactly what I needed.', 'Callum Bauer', true, TRUE, '2026-01-11T01:48:10.076Z'),
  ('AUD-022905715D', 4, 'Idle is smooth again', 'Ordered this for my RS4 B7 after the original gave up at 54k. The spring contact is firm and seated with a definite click. A smear of dielectric grease went on the boot before it was seated. Result is cold starts are smooth instead of shaking the whole car. Good value against the dealer price.', 'Niall Lindqvist', true, TRUE, '2026-08-19T05:55:27.743Z'),
  ('AUD-022905715E', 4, 'Engine light off first drive', 'Cross-referenced the OE number against my 2014 A4 B8.5 before ordering. Coil pack out, new one in, ten minutes with a T30 and the engine cover off. The boot is proper thick silicone, not the thin rubber the cheap ones use. Result is cold starts are smooth instead of shaking the whole car. Will be back for the other side.', 'Viktor Novotny', true, TRUE, '2025-10-13T06:01:46.526Z'),
  ('AUD-022905715E', 5, 'Cured my P0303', 'Bought for a 2010 S4 B8. I replaced all four at once rather than chase them one at a time. The part number on the body matches the OE reference exactly. Result is it pulls cleanly through the rev range again with no stumble under load. Exactly what I needed.', 'Yusuf Bergmann', false, TRUE, '2025-04-01T21:41:14.976Z'),
  ('AUD-022905715E', 5, 'No more limp mode', 'Bought for a 2017 A8 D4. The spring contact is firm and seated with a definite click. I replaced all four at once rather than chase them one at a time. Result is it pulls cleanly through the rev range again with no stumble under load. Good value against the dealer price.', 'Sofia Bauer', true, TRUE, '2026-07-08T06:41:11.821Z'),
  ('AUD-022905715E', 5, 'Misfire cleared instantly', 'Replacement for my 2018 A6 C7 1.4 TFSI. I cleared the fault codes afterwards and they have not come back. Identical moulding and connector to the failed original I took out. Result is cold starts are smooth instead of shaking the whole car.', 'Nora Castellanos', true, TRUE, '2025-04-29T09:29:32.299Z'),
  ('AUD-022905715E', 4, 'Idle is smooth again', 'Replacement for my 2007 RS4 B7 2.0 TFSI. Identical moulding and connector to the failed original I took out. I swapped it on the roadside when the car dropped a cylinder on the way home. Result is the rough idle and flashing engine light disappeared immediately. Good value against the dealer price.', 'Simone Rahman', true, TRUE, '2025-09-20T14:58:30.208Z'),
  ('AUD-022905715E', 2, 'Failed after two months', 'Second one of these I have bought, this time for the A6 C8. It started misfiring on the same cylinder again after about eight weeks. Would not order the same one again.', 'Nora Adeyemi', false, TRUE, '2025-07-16T04:13:06.696Z'),
  ('AUD-032905106F', 4, 'Misfire cleared instantly', 'Went on my A3 8P 1.8 TFSI at 123k miles. I swapped it on the roadside when the car dropped a cylinder on the way home. Identical moulding and connector to the failed original I took out. Result is the rough idle and flashing engine light disappeared immediately.', 'Malik Novak', false, TRUE, '2025-12-31T18:51:50.792Z'),
  ('AUD-032905106F', 5, 'Cured my P0303', 'Went on my S4 B8 1.4 TFSI at 151k miles. I replaced all four at once rather than chase them one at a time. The spring contact is firm and seated with a definite click. Result is no stored codes after a month of daily driving. Will be back for the other side.', 'Nadia Vogel', false, TRUE, '2026-02-22T10:24:38.947Z'),
  ('AUD-032905106F', 4, 'Idle is smooth again', 'Went on my A6 C7 2.0 TFSI at 139k miles. I cleared the fault codes afterwards and they have not come back. The part number on the body matches the OE reference exactly. Result is it pulls cleanly through the rev range again with no stumble under load. Exactly what I needed.', 'Oscar Krause', false, TRUE, '2025-04-05T15:19:51.898Z'),
  ('AUD-03H115403J', 1, 'Wrong housing diameter', 'Bought for a 2007 RS4 B7. The outer diameter was a couple of millimetres off and it would not sit square in the housing. Would not order the same one again.', 'Talia Castellanos', true, TRUE, '2025-09-14T01:52:19.027Z'),
  ('AUD-03H115403J', 1, 'Wrong housing diameter (A6 C7)', 'Ordered this for my A6 C7 after the original gave up at 133k. The outer diameter was a couple of millimetres off and it would not sit square in the housing. Would not order the same one again.', 'Emre Halvorsen', true, TRUE, '2025-04-19T09:47:18.787Z'),
  ('AUD-03H115403J', 5, 'Genuine quality for less', 'Bought for a 2014 A4 B8.5. Two minutes behind the glovebox once I had the tabs released. The media feels dense and the end caps are properly bonded rather than glued on thin. Result is shifts are smoother now the transmission has clean fluid and a fresh filter.', 'Yara Zimmer', true, TRUE, '2026-03-15T05:42:06.041Z'),
  ('AUD-04E109119F', 4, 'Rattle on start-up gone', 'Second one of these I have bought, this time for the A4 B8. A weekend job with the right locking kit and a service manual open next to me. The date stamp was recent, which matters for rubber that has been sitting on a shelf. Result is the top-end rattle on cold start has completely gone. Cannot fault it.', 'Ines Moreau', false, TRUE, '2026-04-16T14:24:27.637Z'),
  ('AUD-04E109119F', 2, 'Stretched sooner than expected', 'Cross-referenced the OE number against my 2013 A4 B8.5 before ordering. It developed a light rattle again far sooner than a timing job should need redoing. Would not order the same one again.', 'Tobias Almeida', true, TRUE, '2025-03-10T07:25:49.676Z'),
  ('AUD-04E109119F', 4, 'Quiet engine again', 'Cross-referenced the OE number against my 2014 Q7 4L before ordering. The tooth profile and belt width are indistinguishable from the part that came off. I booked it in with a specialist rather than risk an interference engine on the driveway. Result is the top-end rattle on cold start has completely gone. Good value against the dealer price.', 'Callum Haugen', true, TRUE, '2025-03-08T07:41:22.131Z'),
  ('AUD-04E109119F', 5, 'Correct kit, no surprises', 'Replacement for my 2016 A6 C7 1.8 TFSI. I booked it in with a specialist rather than risk an interference engine on the driveway. The date stamp was recent, which matters for rubber that has been sitting on a shelf. Result is the engine is noticeably quieter at idle than it has been for a year. Delivery was quick too.', 'Malik Silva', false, TRUE, '2026-02-11T23:47:59.336Z'),
  ('AUD-04E109119F', 5, 'Complete and correct', 'Fitted to my 2017 S3 8V. The chain has proper hardened links rather than the soft pins on cheap copies. I booked it in with a specialist rather than risk an interference engine on the driveway. Result is the top-end rattle on cold start has completely gone.', 'Jonas Tran', true, TRUE, '2025-09-18T07:06:14.756Z'),
